import sys
sys.setrecursionlimit(10000)
n=15
length=2*n
fixed={3:2,11:14,13:11,26:14,27:7,28:10}
seq=[0]*length
for i,v in fixed.items():
    seq[i]=v

def backtrack(v):
    if v>n:
        return True
    positions=[i for i,x in enumerate(seq) if x==v]
    if len(positions)==2:
        return backtrack(v+1)
    # need to place
    for i in range(length):
        j=i+v+1
        if j>=length: continue
        if (seq[i]==0 or seq[i]==v) and (seq[j]==0 or seq[j]==v):
            if len(positions)==1:
                p=positions[0]
                if i!=p and j!=p:
                    continue
                if i!=p:
                    i,j=j,i
            # avoid overwriting other fixed different values
            old_i,old_j=seq[i],seq[j]
            seq[i]=seq[j]=v
            if backtrack(v+1):
                return True
            seq[i],seq[j]=old_i,old_j
    return False

if backtrack(1):
    print(seq)
else:
    print('UNSAT')
